// Keep the original messages; archive only changes who can view the conversation.
async function archiveChats(db,now=Date.now()){
 return db.prepare(`UPDATE chats SET archived_at=last_activity+86400000
 WHERE archived_at IS NULL AND last_activity<=?
 AND NOT EXISTS (SELECT 1 FROM calls WHERE calls.chat=chats.id AND
 ((state='ringing' AND created>?) OR (state='connected' AND visitor_seen>? AND admin_seen>?)))`)
 .bind(now-86400000,now-45000,now-25000,now-25000).run();
}

async function callsApi(r,env,{db,admin,body,json,err,text,uid}){
 // SDP is a wire format: preserve its CRLF line endings, including the final one.
 const description=value=>{if(typeof value!=='string'||value.length>30000||!value.startsWith('v=0\r\n')||!value.endsWith('\r\n'))err('Invalid call description. Please start a new call.');return value};
 const p=new URL(r.url).pathname,method=r.method,now=Date.now();
 const run=(q,...v)=>db.prepare(q).bind(...v).run(),first=(q,...v)=>db.prepare(q).bind(...v).first(),all=async(q,...v)=>(await db.prepare(q).bind(...v).all()).results;
 const isAdmin=p.startsWith('/api/admin/voice');if(isAdmin)await admin();
 let d=method==='POST'?await body(r):{},chat=r.headers.get('X-Chat-Id')||d.chat;
 if(!isAdmin){await archiveChats(db);const t=r.headers.get('X-Chat-Token')||d.token;if(!chat||!t||!await first('SELECT id FROM chats WHERE id=? AND token=?',chat,t))err('Please start a chat before calling.',403);if((await first('SELECT archived_at FROM chats WHERE id=?',chat)).archived_at!==null)err('Your previous chat is archived. Please start a new chat before calling.',410)}
 await run("UPDATE calls SET state='ended' WHERE (state='ringing' AND created<?) OR (state='connected' AND (visitor_seen<? OR admin_seen<?))",now-45000,now-25000,now-25000);
 const route=p.replace(/^\/api\/(admin\/)?voice\/?/,'');
 if(route==='ice'&&method==='GET'){
  if(env.TURN_KEY_ID&&env.TURN_KEY_API_TOKEN){
   const response=await fetch('https://rtc.live.cloudflare.com/v1/turn/keys/'+env.TURN_KEY_ID+'/credentials/generate-ice-servers',{method:'POST',headers:{Authorization:'Bearer '+env.TURN_KEY_API_TOKEN,'Content-Type':'application/json'},body:JSON.stringify({ttl:3600}),signal:AbortSignal.timeout(8000)});
   if(!response.ok)err('Call connection service unavailable. Please use chat for now.',503);
   return json(await response.json());
  }
  return json({iceServers:[{urls:'stun:stun.cloudflare.com:3478'}],relay:false});
 }
 if(route==='presence'){
  if(isAdmin&&method==='POST'){if(d.available===false)await run('DELETE FROM call_presence WHERE id=?','team');else await run('INSERT INTO call_presence VALUES(?,?) ON CONFLICT(id) DO UPDATE SET seen=excluded.seen','team',now)}
  return json({available:!!await first('SELECT id FROM call_presence WHERE id=? AND seen>?','team',now-18000),busy:!!await first("SELECT id FROM calls WHERE state IN ('ringing','connected')")});
 }
 if(route==='incoming'&&isAdmin&&method==='GET')return json(await first("SELECT calls.id,calls.chat,calls.state,chats.name FROM calls JOIN chats ON chats.id=calls.chat WHERE state IN ('ringing','connected') LIMIT 1")||null);
 if(route==='start'&&!isAdmin&&method==='POST'){
  if(!await first('SELECT id FROM call_presence WHERE id=? AND seen>?','team',now-18000))err('The team is not taking calls right now. Please leave a message.',409);
  const recent=await first('SELECT count(*) n FROM calls WHERE chat=? AND created>?',chat,now-300000);if(recent.n>=5)err('Please wait a few minutes before calling again.',429);
  if(await first("SELECT id FROM calls WHERE state IN ('ringing','connected')"))err('The team is on another call. Please try again shortly.',409);
  const offer=description(d.offer);const id=uid();try{await run("INSERT INTO calls(id,chat,state,offer,created,visitor_seen) VALUES(?,?,'ringing',?,?,?)",id,chat,offer,now,now)}catch{err('The team is on another call. Please try again shortly.',409)}return json({id});
 }
 const parts=route.split('/'),id=parts[0],action=parts[1];const c=await first('SELECT * FROM calls WHERE id=?',id);if(!c||(!isAdmin&&c.chat!==chat))err('Call not found.',404);
 if(method==='GET'){
  if(!['ended','declined'].includes(c.state))await run('UPDATE calls SET '+(isAdmin?'admin_seen':'visitor_seen')+'=? WHERE id=?',now,id);
  const after=Number(new URL(r.url).searchParams.get('after')||0);const signals=await all('SELECT seq,candidate FROM call_signals WHERE call=? AND sender=? AND seq>? ORDER BY seq LIMIT 100',id,isAdmin?'visitor':'admin',Number.isSafeInteger(after)?after:0);
  return json({id,state:c.state,offer:isAdmin?c.offer:undefined,answer:c.answer,signals});
 }
 if(method==='POST'&&action==='end'){await run("UPDATE calls SET state=? WHERE id=? AND state IN ('ringing','connected')",d.decline&&isAdmin?'declined':'ended',id);await run('DELETE FROM call_signals WHERE call=?',id);return json({ok:true})}
 if(method==='POST'&&action==='answer'&&isAdmin){if(c.state!=='ringing')err('This call is no longer ringing.',409);const answer=description(d.answer);const result=await run("UPDATE calls SET answer=?,state='connected',admin_seen=? WHERE id=? AND state='ringing'",answer,now,id);if(result.meta?.changes===0)err('Call already answered.',409);return json({ok:true})}
 if(method==='POST'&&action==='candidate'){if(!['ringing','connected'].includes(c.state))err('Call ended.',409);const n=await first('SELECT count(*) n FROM call_signals WHERE call=?',id);if(n.n>=150)err('Too many connection updates.',429);const candidate=text(d.candidate,4000);try{const parsed=JSON.parse(candidate);if(typeof parsed.candidate!=='string')err('Invalid connection update.')}catch{err('Invalid connection update.')}await run('INSERT INTO call_signals(call,sender,candidate) VALUES(?,?,?)',id,isAdmin?'admin':'visitor',candidate);return json({ok:true})}
 if(route==='ice')err('Not found.',404);err('Not found.',404);
}

const json=(data,status=200,headers={})=>Response.json(data,{status,headers:{'Cache-Control':'no-store',...headers}});const uid=()=>crypto.randomUUID();const token=()=>uid()+uid();const err=(m,s=400)=>{throw Object.assign(Error(m),{status:s})};const text=(v,n)=>{if(typeof v!=='string'||!v.trim()||v.length>n)err('Please complete the required fields.');return v.trim()};
async function body(r){if(Number(r.headers.get('content-length'))>3000000)err('Upload too large.',413);const s=await r.text();if(s.length>3000000)err('Upload too large.',413);try{return JSON.parse(s)}catch{err('Invalid request.')}}
export async function api(r,env){try{if(!env.DB)err('Service is being set up. Please try again shortly.',503);const db=env.DB,p=new URL(r.url).pathname,method=r.method;const run=(q,...v)=>db.prepare(q).bind(...v).run(),first=(q,...v)=>db.prepare(q).bind(...v).first(),all=async(q,...v)=>(await db.prepare(q).bind(...v).all()).results;
if(method!=='GET'&&r.headers.get('Origin')!==new URL(r.url).origin)err('Request origin not allowed.',403);
if(p==='/api/login'&&method==='POST'){const ip=r.headers.get('CF-Connecting-IP')||'local',now=Date.now(),a=await first('SELECT * FROM attempts WHERE ip=?',ip);if(a&&a.reset>now&&a.count>=8)err('Too many attempts. Please try again in 15 minutes.',429);const d=await body(r);if(!env.ADMIN_EMAIL||!env.ADMIN_PASSWORD)err('Admin login is not configured.',503);if(d.email!==env.ADMIN_EMAIL||d.password!==env.ADMIN_PASSWORD){await run('INSERT INTO attempts(ip,count,reset) VALUES(?,1,?) ON CONFLICT(ip) DO UPDATE SET count=CASE WHEN reset<? THEN 1 ELSE count+1 END,reset=CASE WHEN reset<? THEN ? ELSE reset END',ip,now+900000,now,now,now+900000);err('Incorrect email or password.',401)}await run('DELETE FROM attempts WHERE ip=?',ip);const t=token();await run('DELETE FROM sessions WHERE expires<?',now);await run('INSERT INTO sessions VALUES(?,?)',t,now+28800000);return json({ok:true},200,{'Set-Cookie':'brm_session='+t+'; HttpOnly; Secure; SameSite=Strict; Path=/; Max-Age=28800'})}
const session=r.headers.get('Cookie')?.match(/(?:^|; )brm_session=([^;]+)/)?.[1];const admin=async()=>{if(!session||!await first('SELECT token FROM sessions WHERE token=? AND expires>?',session,Date.now()))err('Please sign in.',401)};
if(/^\/api\/(admin\/)?voice(?:\/|$)/.test(p))return await callsApi(r,env,{db,admin,body,json,err,text,uid});
if(p==='/api/logout'&&method==='POST'){if(session)await run('DELETE FROM sessions WHERE token=?',session);return json({ok:true},200,{'Set-Cookie':'brm_session=; HttpOnly; Secure; SameSite=Strict; Path=/; Max-Age=0'})}
if(p==='/api/clients'&&method==='GET')return json(await all('SELECT * FROM clients ORDER BY created DESC'));
if(p.startsWith('/api/admin/')){await admin();if(p==='/api/admin/session')return json({ok:true});
if(p==='/api/admin/chats'&&method==='GET'){
 await archiveChats(db);const params=new URL(r.url).searchParams,archived=params.get('archived')==='1',search=(params.get('search')||'').slice(0,200).trim(),offset=Math.max(0,Math.min(1000000,Number(params.get('offset'))||0));
 return json(await all(`SELECT c.id,c.name,c.created,c.last_activity,c.archived_at,
 (SELECT count(*) FROM messages m WHERE m.chat=c.id) count,
 (SELECT sender FROM messages m WHERE m.chat=c.id ORDER BY created DESC,rowid DESC LIMIT 1) last_sender
 FROM chats c WHERE c.archived_at IS ${archived?'NOT NULL':'NULL'}
 AND (?='' OR instr(lower(c.name),lower(?))>0 OR EXISTS(SELECT 1 FROM messages m WHERE m.chat=c.id AND instr(lower(m.body),lower(?))>0))
 ORDER BY ${archived?'c.archived_at':'c.last_activity'} DESC,c.id DESC LIMIT 50 OFFSET ?`,search,search,search,Math.floor(offset)));
}
if(p.startsWith('/api/admin/chats/')){
 await archiveChats(db);const id=p.split('/').pop(),conversation=await first('SELECT id,archived_at FROM chats WHERE id=?',id);if(!conversation)err('Conversation not found.',404);
 if(method==='GET')return json(await all('SELECT id,sender,body,created FROM messages WHERE chat=? ORDER BY created,rowid',id));
 if(method==='POST'){
  if(conversation.archived_at!==null)err('This conversation is archived. Its history is read-only.',409);
  const d=await body(r),result=await run("INSERT INTO messages(id,chat,sender,body,created) SELECT ?,id,'team',?,? FROM chats WHERE id=? AND archived_at IS NULL",uid(),text(d.body,2000),Date.now(),id);
  if((result.meta?.changes??result.changes)===0)err('This conversation is archived. Its history is read-only.',409);return json({ok:true});
 }
}
if(p==='/api/admin/clients'&&method==='POST'){const d=await body(r),id=d.id||uid(),old=d.id?await first('SELECT * FROM clients WHERE id=?',id):null;if(d.id&&!old)err('Client not found.',404);let image=d.image||old?.image;if(!image||!/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(image)||image.length>2800000)err('Please upload a PNG, JPEG or WebP image smaller than 2 MB.');const links=['google','apple','huawei'].map(k=>{if(!d[k])return '';let url;try{url=new URL(d[k])}catch{err('Please enter a valid store URL.')}const hosts={google:['play.google.com'],apple:['apps.apple.com'],huawei:['appgallery.huawei.com','appgallery.cloud.huawei.com']};if(url.protocol!=='https:'||!hosts[k].includes(url.hostname))err('Please use the official '+k+' store HTTPS link.');return url.href});await run('INSERT INTO clients VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET name=excluded.name,description=excluded.description,image=excluded.image,google=excluded.google,apple=excluded.apple,huawei=excluded.huawei',id,text(d.name,120),text(d.description,2000),image,...links,old?.created||Date.now());return json({ok:true})}
if(p.startsWith('/api/admin/clients/')&&method==='DELETE'){await run('DELETE FROM clients WHERE id=?',p.split('/').pop());return json({ok:true})}err('Not found.',404)}
if(p==='/api/chat'&&method==='POST'){const d=await body(r);const ip=r.headers.get('CF-Connecting-IP')||'local',now=Date.now(),key='chat:'+ip;const a=await first('SELECT * FROM attempts WHERE ip=?',key);if(a&&a.reset>now&&a.count>=10)err('Please wait before starting another conversation.',429);await run('INSERT INTO attempts VALUES(?,1,?) ON CONFLICT(ip) DO UPDATE SET count=CASE WHEN reset<? THEN 1 ELSE count+1 END,reset=CASE WHEN reset<? THEN ? ELSE reset END',key,now+3600000,now,now,now+3600000);const id=uid(),t=token();await run('INSERT INTO chats(id,token,name,created,last_activity) VALUES(?,?,?,?,?)',id,t,text(d.name,80),now,now);return json({id,token:t})}
if(p.startsWith('/api/chat/')){
 const id=p.split('/').pop(),d=method==='POST'?await body(r):{},t=r.headers.get('X-Chat-Token')||d.token;
 if(!t||!await first('SELECT id FROM chats WHERE id=? AND token=?',id,t))err('Conversation unavailable. Please use the browser where you started this chat.',403);
 await archiveChats(db);const conversation=await first('SELECT archived_at FROM chats WHERE id=?',id);
 if(conversation.archived_at!==null)return json({archived:true,error:'Your previous conversation has been archived. Start a new chat to contact the team.'},410);
 if(method==='GET')return json(await all('SELECT id,sender,body,created FROM messages WHERE chat=? ORDER BY created,rowid',id));
 if(method==='POST'){
  const recent=await first('SELECT count(*) n FROM messages WHERE chat=? AND sender=? AND created>?',id,'visitor',Date.now()-60000);if(recent.n>=20)err('Please wait a moment before sending more messages.',429);
  const result=await run("INSERT INTO messages(id,chat,sender,body,created) SELECT ?,id,'visitor',?,? FROM chats WHERE id=? AND archived_at IS NULL",uid(),text(d.body,2000),Date.now(),id);
  if((result.meta?.changes??result.changes)===0)return json({archived:true,error:'Your previous conversation has been archived. Start a new chat to contact the team.'},410);return json({ok:true});
 }
}
err('Not found.',404)}catch(e){return json({error:e.status?e.message:'The service is temporarily unavailable. Please try again.'},e.status||500)}}

const assets={"/":{"body":"<!doctype html><html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"description\" content=\"Custom mobile apps for artists and personal brands. Speak to Black R Media about your app, browse our clients and download their apps.\"><title>Black R Media — Artist & Personal Apps</title><link rel=\"stylesheet\" href=\"/style.css\"></head><body>\n<header><a class=\"brand\" href=\"/\" aria-label=\"Black R Media home\"><img src=\"/logo.png\" alt=\"Black R Media\"></a><nav><a href=\"#approach\">What we do</a><a href=\"#clients\">Our clients</a><a href=\"#process\">The process</a></nav><button class=\"small dark\" data-chat>Let's talk <span>↗</span></button></header>\n<main><section class=\"hero\"><div class=\"hero-copy\"><div class=\"eyebrow\"><i></i> APPS FOR ARTISTS & PERSONAL BRANDS</div><h1>Your name.<br>Your content.<br><em>Your own app.</em></h1><p>We build mobile apps for artists and personal brands. Give your supporters one place to find your music, follow your updates and keep in touch.</p><div class=\"actions\"><button class=\"dark\" data-chat>Let's build your app <span>↗</span></button><a href=\"#clients\" class=\"text-link\">See our clients <span>↓</span></a></div><div class=\"hero-note\"><span class=\"mini-mark\">B<span>R</span></span><p>Designed for your brand.<br><strong>Built by Black R Media.</strong></p></div></div><div class=\"hero-art\"><div class=\"orbit orbit-one\"></div><div class=\"orbit orbit-two\"></div><div class=\"art-label\">A LOOK AT YOUR NEXT APP</div><div class=\"phone\"><div class=\"notch\"></div><div class=\"phone-top\">9:41 <span>▮▮ ◕ ▰</span></div><div class=\"app-head\">THE ARTIST CLUB <span>☰</span></div><div class=\"artist-visual\"><div class=\"disc\"></div><span>NEW MUSIC.<br>LISTEN NOW.</span><small>LATEST RELEASE / VOL. 01</small></div><div class=\"app-content\"><small>MUSIC · NEWS · UPDATES</small><h3>New releases.<br>Latest updates.</h3><div class=\"track\"><span class=\"play\">▶</span><div>Listen to the latest track<small>Available in the app</small></div><span>♡</span></div><div class=\"app-tiles\"><div>↗<small>Latest releases</small></div><div>✦<small>Behind the scenes</small></div></div></div><div class=\"phone-nav\">⌂　 ♫　 ◉　 ♡</div></div><div class=\"floating-tag\"><span>✦</span><div>Your name. Your look.<small>An app that feels like you.</small></div></div><div class=\"art-bottom\">ARTISTS · CREATORS · PERSONAL BRANDS <span>01 — BRM</span></div><span class=\"concept\">Example app design</span></div></section>\n<div class=\"ticker\"><span>ARTIST & PERSONAL APPS</span><b>✦</b><span>MUSIC · CONTENT · UPDATES</span><b>✦</b><span>BUILT BY BLACK R MEDIA.</span><b>✦</b></div>\n<section id=\"approach\" class=\"section\"><div class=\"section-heading\"><div><div class=\"eyebrow\">01 / WHAT WE DO</div><h2>An app that fits<br>what you do.</h2></div><p>Whether you’re releasing music or building a personal brand, we’ll help you work out what your app needs and build it with you.</p></div><div class=\"services\"><article><span>01 <b>↗</b></span><h3>Artist apps</h3><p>Let fans find your music, read your news and follow your work in an app with your name and branding.</p><small>MUSIC, NEWS & ARTIST UPDATES</small></article><article><span>02 <b>◎</b></span><h3>Personal brand apps</h3><p>Share your work, content and updates with the people who follow you. We design the app to suit you and what you offer.</p><small>YOUR CONTENT & UPDATES</small></article><article><span>03 <b>✦</b></span><h3>From idea to launch</h3><p>We handle the design and development. Together, we’ll agree on the features, review the app and prepare it for the stores you choose.</p><small>DESIGN, DEVELOPMENT & STORE PREPARATION</small></article></div></section>\n<section id=\"clients\" class=\"section clients-section\"><div class=\"section-heading\"><div><div class=\"eyebrow\">02 / OUR CLIENTS</div><h2>Meet our clients.<br>Get their apps.</h2></div><p>Take a look at the artists and personal brands we work with. Read about each client and use the store links to download their app.</p></div><div id=\"client-list\" class=\"client-grid\"><p>Loading clients…</p></div><div class=\"client-bottom\"><span>Want an app of your own?</span><button class=\"text-link\" data-chat>Chat with us ↗</button></div></section>\n<section id=\"process\" class=\"section\"><div class=\"eyebrow\">03 / THE PROCESS</div><h2>How we work<br>with you.</h2><div class=\"steps\"><article><span>01 / TELL US ABOUT IT</span><h3>What do you have in mind?</h3><p>Send us a message about yourself and the app you want. If you’re unsure where to start, we can talk through the options.</p></article><article><span>02 / DESIGN & BUILD</span><h3>We get to work.</h3><p>We agree on what to include, then design and build your app. You’ll review the work with us as it takes shape.</p></article><article><span>03 / REVIEW & RELEASE</span><h3>Get ready to share it.</h3><p>Once you’re happy with the app, we help prepare it for release. We’ll explain the store requirements and what happens next.</p></article></div></section>\n<section class=\"cta\"><div class=\"eyebrow\">HAVE AN APP IN MIND?</div><h2>Let’s talk<br><em>about it.</em></h2><button data-chat>Talk to Black R Media <span>↗</span></button><p>Send us a message below. You don’t need an account.</p></section></main>\n<footer><a class=\"brand\" href=\"/\"><img src=\"/logo.png\" alt=\"Black R Media\"></a><p>Artist and personal apps by Black R Media.</p><div><span>© <span id=\"year\"></span> Black R Media</span><a class=\"admin-link\" href=\"/admin\" aria-label=\"Admin login\">Admin</a></div></footer>\n<button id=\"chat-launch\" aria-label=\"Chat with Black R Media\"><span>☏</span> Let's chat <i></i></button><aside id=\"chat-panel\" hidden aria-label=\"Chat with Black R Media\"><div class=\"chat-header\"><div class=\"avatar\">BR</div><div><strong>Black R Media</strong><small>Leave a message for our team</small></div><button id=\"chat-close\" aria-label=\"Close chat\">×</button></div><div id=\"visitor-voice\" class=\"voice-box\"><button id=\"voice-start\" type=\"button\" disabled>Call the team</button><span id=\"voice-status\" role=\"status\">Start a chat to make a voice call.</span><div id=\"voice-controls\" hidden><button id=\"voice-mute\" type=\"button\">Mute</button><button id=\"voice-end\" type=\"button\" class=\"voice-end\">End call</button></div></div><div id=\"chat-messages\" aria-live=\"polite\"><div class=\"bubble team\">Hi, welcome to Black R Media. What kind of app are you looking for?</div></div><form id=\"chat-start\"><label>Your name<input name=\"name\" maxlength=\"80\" required placeholder=\"Enter your name\"></label><p>Chats clear after 24 hours without a message. Our team retains archived history for future reference. Please avoid sharing sensitive information.</p><button class=\"dark\">Start chat ↗</button></form><form id=\"chat-send\" hidden><input name=\"body\" maxlength=\"2000\" required placeholder=\"Type your message…\" aria-label=\"Message\"><button aria-label=\"Send message\">➤</button></form><div id=\"chat-status\" role=\"status\"></div><small class=\"chat-foot\">Our team will reply here.</small></aside><script src=\"/app.js\" defer></script><script src=\"/voice.js\" defer></script></body></html>\n","type":"text/html"},"/admin":{"body":"<!doctype html><html lang=\"en\"><head><meta charset=\"UTF-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"robots\" content=\"noindex,nofollow\"><title>Management — Black R Media</title><link rel=\"stylesheet\" href=\"/style.css\"></head><body><header><a class=\"brand\" href=\"/\"><img src=\"/logo.png\" alt=\"Black R Media\"></a><a class=\"text-link\" href=\"/\">View website ↗</a></header><main class=\"admin\"><section id=\"login\" class=\"panel login\"><div class=\"eyebrow\">BLACK R MEDIA / MANAGEMENT</div><h2>Welcome back.</h2><p class=\"hint\">Sign in to manage your clients and conversations.</p><form id=\"login-form\"><label>Email<input type=\"email\" name=\"email\" required autocomplete=\"username\"></label><label>Password<input type=\"password\" name=\"password\" required autocomplete=\"current-password\"></label><button class=\"dark\">Sign in ↗</button><p id=\"login-error\" class=\"status\" role=\"alert\"></p></form></section><section id=\"dashboard\" hidden><div class=\"admin-top\"><div><div class=\"eyebrow\">BLACK R MEDIA / MANAGEMENT</div><h2>Clients & messages</h2></div><button id=\"logout\" class=\"text-link\">Sign out ↗</button></div><div class=\"admin-layout\"><section class=\"panel\"><h2>Conversations</h2><div class=\"inbox-tabs\" aria-label=\"Conversation view\"><button id=\"inbox-tab\" type=\"button\" aria-pressed=\"true\">Inbox</button><button id=\"archive-tab\" type=\"button\" aria-pressed=\"false\">Archive</button></div><label id=\"archive-search-label\" hidden>Search archived conversations<input id=\"archive-search\" type=\"search\" maxlength=\"200\" placeholder=\"Client name or message text\"></label><div id=\"admin-voice\" class=\"voice-box\"><label class=\"voice-toggle\"><input type=\"checkbox\" id=\"voice-available\"> Available for voice calls</label><span id=\"voice-status\" role=\"status\">Switch on when you can take calls. Keep this dashboard open.</span><div id=\"incoming-call\" hidden><strong id=\"caller-name\"></strong><button id=\"voice-answer\" type=\"button\">Answer</button><button id=\"voice-decline\" type=\"button\">Decline</button></div><div id=\"voice-controls\" hidden><button id=\"voice-mute\" type=\"button\">Mute</button><button id=\"voice-end\" type=\"button\" class=\"voice-end\">End call</button></div></div><p class=\"hint\">Replies appear directly in the visitor’s chat. Chats clear from the visitor’s chatbox and move to Archive after 24 hours without a message. Archived messages remain available here.</p><div id=\"conversations\" class=\"admin-chat-list\"></div><div class=\"inbox-pages\"><button id=\"chats-previous\" type=\"button\" disabled>Previous</button><button id=\"chats-next\" type=\"button\" disabled>Next</button></div><p id=\"archive-note\" class=\"hint\" hidden></p><h3 id=\"chat-title\">Select a conversation</h3><div id=\"admin-messages\" aria-live=\"polite\"></div><form id=\"reply-form\" hidden><label>Your reply<textarea name=\"body\" maxlength=\"2000\" required></textarea></label><button class=\"dark\">Send reply ↗</button></form><p id=\"inbox-status\" class=\"status\" role=\"status\"></p></section><section class=\"panel\"><h2 id=\"client-title\">Add a client</h2><p class=\"hint\">Add a photo and a short description. All app store links are optional; you can publish a client without any links.</p><form id=\"client-form\"><input type=\"hidden\" name=\"id\"><label>Artist / client name<input name=\"name\" maxlength=\"120\" required></label><label>Brief description<textarea name=\"description\" maxlength=\"2000\" required></textarea></label><label>Client image<input type=\"file\" name=\"image\" accept=\"image/png,image/jpeg,image/webp\"></label><p class=\"hint\">PNG, JPEG or WebP. Maximum 2 MB. Choose an image when creating a client; keep the existing image when editing.</p><label>Google Play URL (optional)<input type=\"url\" name=\"google\" placeholder=\"https://play.google.com/store/apps/…\"></label><label>Apple App Store URL (optional)<input type=\"url\" name=\"apple\" placeholder=\"https://apps.apple.com/…\"></label><label>Huawei AppGallery URL (optional)<input type=\"url\" name=\"huawei\" placeholder=\"https://appgallery.huawei.com/…\"></label><button class=\"dark\">Publish client ↗</button> <button type=\"button\" id=\"cancel-edit\" class=\"text-link\" hidden>Cancel edit</button><p id=\"client-status\" class=\"status\" role=\"status\"></p></form><h3>Published clients</h3><div id=\"admin-clients\"></div></section></div></section></main><script src=\"/app.js\" defer></script><script src=\"/admin.js\" defer></script><script src=\"/voice.js\" defer></script></body></html>\n","type":"text/html"},"/style.css":{"body":"@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@400;500;600;700;800&display=swap');\n:root{--red:#ed262a;--ink:#171716;--cream:#f8f7f3;--muted:#6a6a66;--line:#deded7}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:90px}body{margin:0;background:var(--cream);color:var(--ink);font-family:'DM Sans',sans-serif}button,input,textarea{font:inherit}button,a{-webkit-tap-highlight-color:transparent}button{cursor:pointer;border:0}a{color:inherit;text-decoration:none}button:focus-visible,a:focus-visible{outline:3px solid var(--red);outline-offset:5px}header{height:108px;display:flex;align-items:center;justify-content:space-between;padding:18px 6%;border-bottom:1px solid var(--line)}.brand img{width:145px;display:block}nav{display:flex;gap:35px;font-size:13px}nav a:hover{color:var(--red)}button,.text-link{font-weight:600}.dark{background:var(--ink);color:white;padding:19px 25px;border-radius:4px}.dark span{margin-left:30px}.small{padding:13px 18px;font-size:13px}.hero{display:grid;grid-template-columns:1fr 1fr;min-height:690px}.hero-copy{padding:65px 8% 45px 12%}.eyebrow{font-size:10px;letter-spacing:2px;font-weight:700;display:flex;align-items:center;gap:9px}.eyebrow i{width:7px;height:7px;background:var(--red);border-radius:50%}h1,h2,h3{font-family:Manrope,sans-serif;letter-spacing:-2px;margin:20px 0}h1{font-size:clamp(48px,5.4vw,82px);line-height:1.08;font-weight:800}em{font-style:normal;color:var(--red)}.hero-copy>p{font-size:15px;line-height:1.8;max-width:390px;color:var(--muted)}.actions{display:flex;align-items:center;gap:26px;margin-top:30px;font-size:12px}.text-link{background:none;padding:0;font-size:12px}.text-link span{margin-left:12px}.hero-note{display:flex;gap:14px;align-items:center;margin-top:43px}.mini-mark{font-weight:800;font-size:25px;letter-spacing:-5px}.mini-mark span{color:var(--red)}.hero-note p{font-size:10px;line-height:1.7;color:var(--muted)}.hero-note strong{color:var(--ink);font-weight:500}.hero-art{position:relative;background:#e9e8e1;overflow:hidden;display:flex;align-items:center;justify-content:center;padding:50px 20px 70px;background-image:radial-gradient(#c8c6bc 1px,transparent 1px);background-size:16px 16px}.art-label{position:absolute;top:30px;left:35px;font-size:9px;letter-spacing:2px}.orbit{position:absolute;width:500px;height:500px;border:1px solid #cbc8bf;border-radius:50%;transform:rotate(-30deg)}.orbit-two{width:650px;height:350px}.phone{width:252px;height:515px;border:7px solid #222;border-radius:37px;background:#fcfbf7;position:relative;transform:rotate(-8deg);box-shadow:20px 30px 45px #29272245;z-index:2;overflow:hidden}.notch{position:absolute;width:76px;height:19px;left:82px;top:0;background:#222;border-radius:0 0 14px 14px}.phone-top{display:flex;justify-content:space-between;font-size:8px;font-weight:bold;padding:12px 15px}.app-head{padding:18px 14px;font-size:10px;font-weight:800;letter-spacing:1px;display:flex;justify-content:space-between}.artist-visual{height:203px;background:#e72b2e;position:relative;overflow:hidden;padding:30px 18px;color:#fff}.artist-visual>span{position:relative;font-size:35px;font-weight:800;line-height:1;letter-spacing:-2px;display:block;z-index:2}.artist-visual>small{position:absolute;bottom:13px;font-size:6px;letter-spacing:1.4px}.disc{position:absolute;right:-60px;top:-40px;border-radius:50%;width:250px;height:250px;background:repeating-radial-gradient(#171716 0px,#171716 3px,#333 4px,#171716 5px);box-shadow:0 15px 25px #0006}.disc:after{content:'';position:absolute;inset:95px;border-radius:50%;background:#eabfb6;border:20px solid #ec393d}.app-content{padding:17px 14px}.app-content>small{font-size:6px;letter-spacing:1.4px}.app-content h3{font-size:18px;letter-spacing:-.7px;line-height:1.2;margin:8px 0 14px}.track{display:flex;gap:9px;align-items:center;font-size:7px}.track small{display:block;color:#777;font-size:6px;margin-top:4px}.play{padding:10px;background:var(--red);color:#fff;border-radius:50%}.app-tiles{display:flex;gap:10px;margin-top:16px}.app-tiles>div{background:#e8e6dd;padding:10px;width:50%;font-size:20px}.app-tiles small{display:block;font-size:7px;margin-top:8px}.phone-nav{text-align:center;border-top:1px solid #ddd;padding:10px;font-size:13px}.floating-tag{position:absolute;z-index:3;right:8%;bottom:125px;background:#fff;padding:16px 20px;display:flex;gap:14px;align-items:center;box-shadow:0 8px 30px #0001;transform:rotate(5deg);font-size:12px;border-radius:7px}.floating-tag>span{color:var(--red);font-size:28px}.floating-tag small{display:block;font-size:9px;margin-top:5px;color:#777}.art-bottom{position:absolute;bottom:28px;left:30px;right:30px;display:flex;justify-content:space-between;font-size:7px;letter-spacing:1.3px}.concept{position:absolute;font-size:8px;bottom:10px;color:#777}.ticker{background:var(--red);color:white;padding:23px 5%;display:flex;justify-content:space-around;gap:24px;font-size:11px;font-weight:700;letter-spacing:1.4px;overflow:hidden;white-space:nowrap}.ticker b{font-size:18px}.section{padding:90px 6%}.section-heading{display:flex;justify-content:space-between;align-items:end;gap:60px;margin-bottom:38px}h2{font-size:clamp(34px,3.6vw,52px);line-height:1.14;letter-spacing:-2px}.section-heading>p{max-width:335px;color:var(--muted);font-size:14px;line-height:1.8;margin-bottom:20px}.services,.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:30px}.services article{border-top:1px solid var(--ink);padding:23px 8px 0 0}.services article>span{display:flex;justify-content:space-between;font-size:11px}.services b{font-size:27px;font-weight:400}.services h3,.steps h3{font-size:24px;letter-spacing:-.8px;margin-top:30px}.services p,.steps p{font-size:13px;color:var(--muted);line-height:1.8;max-width:310px}.services small{display:block;margin-top:25px;font-size:8px;letter-spacing:1.5px}.clients-section{background:#eeede7}.client-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:25px}.client-card{background:var(--cream);border-radius:5px;overflow:hidden}.client-card img{width:100%;height:260px;object-fit:cover}.client-body{padding:24px}.client-body h3{font-size:24px;letter-spacing:-1px;margin:0 0 12px}.client-body p{font-size:13px;line-height:1.8;color:var(--muted);white-space:pre-line}.stores{display:flex;flex-wrap:wrap;gap:7px;margin-top:20px}.stores a{border:1px solid var(--line);padding:9px;font-size:9px;border-radius:4px}.stores a:hover{background:var(--ink);color:white}.empty-clients{grid-column:1/-1;border:1px solid #d1d0c8;min-height:180px;display:flex;align-items:center;justify-content:space-between;padding:35px;gap:30px}.empty-clients h3{font-size:30px;letter-spacing:-1px;margin:0 0 12px}.empty-clients p{color:var(--muted);font-size:13px}.empty-clients .large-star{font-size:85px;color:var(--red)}.client-bottom{display:flex;justify-content:space-between;border-top:1px solid #d2d1c9;padding-top:25px;margin-top:35px;font-size:13px}.steps{margin-top:45px}.steps article{border-top:1px solid var(--line);padding-top:25px}.steps article>span{font-size:9px;letter-spacing:1px;color:var(--red)}.cta{background:var(--ink);color:var(--cream);padding:70px 6%;position:relative}.cta h2{font-size:clamp(60px,8vw,110px);margin:25px 0}.cta button{position:absolute;right:8%;top:48%;background:var(--red);color:white;padding:22px 28px;border-radius:4px}.cta button span{margin-left:30px}.cta p{font-size:11px;color:#aaa}footer{padding:35px 6%;display:flex;justify-content:space-between;align-items:center;gap:25px}footer p{font-size:11px;color:var(--muted)}footer>div{font-size:9px;display:flex;gap:25px}#chat-launch{position:fixed;right:25px;bottom:24px;z-index:10;background:var(--ink);color:white;border-radius:35px;padding:17px 23px;box-shadow:0 4px 20px #0003;display:flex;gap:13px;align-items:center;font-size:12px}#chat-launch>span{font-size:21px}#chat-launch i{width:7px;height:7px;border-radius:50%;background:#7cd9a5}#chat-panel{position:fixed;right:24px;bottom:90px;width:365px;height:495px;background:#f3f0e9;z-index:20;box-shadow:0 15px 80px #0003;border-radius:13px;overflow:hidden;display:flex;flex-direction:column}#chat-panel[hidden],[hidden]{display:none!important}.chat-header{background:var(--ink);color:white;padding:20px;display:flex;align-items:center;gap:12px}.avatar{border-radius:50%;background:var(--red);padding:12px;font-size:12px}.chat-header strong{font-size:13px}.chat-header small{display:block;font-size:10px;color:#ccc;margin-top:5px}.chat-header button{background:none;color:#fff;font-size:25px;margin-left:auto}#chat-messages{flex:1;padding:18px;overflow-y:auto;display:flex;flex-direction:column;gap:10px}.bubble{padding:12px 14px;border-radius:10px;max-width:85%;font-size:12px;line-height:1.6;white-space:pre-wrap;overflow-wrap:anywhere;background:white;align-self:flex-start}.bubble.visitor{background:#dce9d9;align-self:flex-end}.bubble small{display:block;font-size:8px;opacity:.5;margin-top:5px}#chat-start{padding:0 18px 15px}label{display:block;font-size:12px;font-weight:500}input,textarea{display:block;width:100%;border:1px solid #d0d0ca;background:#fff;padding:12px;border-radius:4px;margin-top:7px;color:var(--ink)}#chat-start p{font-size:9px;color:#777;line-height:1.5}#chat-start button{width:100%;font-size:12px;padding:12px}#chat-send{display:flex;background:white;padding:10px;gap:8px}#chat-send input{border:0;margin:0;font-size:12px}#chat-send button{background:var(--red);color:white;border-radius:50%;width:38px;flex-shrink:0}.chat-foot{text-align:center;font-size:8px;color:#999;padding:9px}#chat-status{font-size:10px;color:#a52222;padding:0 15px}.admin{max-width:1200px;margin:45px auto;padding:0 25px}.admin-top{display:flex;justify-content:space-between;align-items:center}.admin-layout{display:grid;grid-template-columns:1fr 1fr;gap:35px;margin-top:30px}.panel{background:white;padding:25px;border:1px solid var(--line);border-radius:8px}.panel h2{font-size:25px;letter-spacing:-1px}.panel label{margin-top:18px}.panel button{margin-top:15px}.panel textarea{min-height:100px}.login{max-width:430px;margin:80px auto}.admin-chat-list{max-height:230px;overflow:auto}.conversation{display:block;width:100%;padding:13px;text-align:left;background:var(--cream);border-bottom:1px solid var(--line)}.conversation.selected{border-left:3px solid var(--red)}#admin-messages{height:280px;overflow:auto;padding:20px;background:#f3f0e9;display:flex;flex-direction:column;gap:10px}.status{font-size:12px;color:#a52222;line-height:1.6}.admin-client{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line);padding:10px 0;font-size:13px}.danger{color:#b11;background:none}.hint{font-size:11px;color:var(--muted);line-height:1.7}.store-icon{font-size:14px;margin-right:5px}button:disabled{opacity:.5;cursor:wait}@media(min-width:1500px){header,main,footer{max-width:1600px;margin:auto}}@media(max-width:800px){header{height:85px;padding:15px 6%}.brand img{width:115px}nav{display:none}.hero{grid-template-columns:1fr}.hero-copy{padding:45px 6%}.hero h1{font-size:58px}.hero-art{min-height:590px}.section{padding:60px 6%}.section-heading{display:block}.section-heading>p{max-width:100%}.services,.steps{grid-template-columns:1fr;gap:35px}.services article{padding-bottom:10px}.services p,.steps p{max-width:none}.client-grid{grid-template-columns:1fr}.cta button{position:static;margin:5px 0 15px}.cta h2{font-size:70px}footer{flex-wrap:wrap;padding-bottom:100px}footer>div{width:100%;justify-content:space-between}.ticker{justify-content:flex-start}.admin-layout{grid-template-columns:1fr}.actions{gap:20px}.empty-clients{padding:25px}.empty-clients h3{font-size:25px}}@media(max-width:420px){#chat-panel{right:10px;bottom:85px;width:calc(100% - 20px);height:min(510px,calc(100dvh - 110px))}.hero h1{font-size:50px}.actions{flex-wrap:wrap}.hero-art{min-height:560px}.floating-tag{right:5%;bottom:100px}}\n\nfooter .admin-link{font-size:10px;color:var(--muted);font-weight:400}footer .admin-link:hover{color:var(--ink);text-decoration:underline}\n.voice-box{padding:12px 16px;border-bottom:1px solid var(--line);background:#fff;flex-shrink:0}.voice-box>span{display:block;font-size:10px;color:var(--muted);line-height:1.5;margin:7px 0}.voice-box button{padding:8px 12px;border-radius:4px;background:var(--ink);color:#fff;font-size:11px;margin:3px 6px 3px 0}.voice-box .voice-end{background:#b62025}.voice-box .voice-toggle{display:flex;align-items:center;gap:10px;margin:0;font-size:12px}.voice-toggle input{width:16px;height:16px;margin:0}.voice-box strong{display:block;font-size:13px;margin:10px 0}#chat-panel{height:min(610px,calc(100dvh - 110px))}#chat-messages{min-height:80px}#admin-voice{border:1px solid var(--line);border-radius:5px;margin:15px 0}\n#voice-start{background:#15803d;color:#fff;transition:background-color .15s}#voice-start:not(:disabled):hover{background:#166534}#voice-start:disabled{background:#6b7280;color:#fff;opacity:1;cursor:not-allowed}\n\n#voice-start[data-state=\"busy\"]:disabled{background:#c2410c;color:#fff}\n\n.inbox-tabs{display:flex;gap:8px;margin-bottom:12px}.inbox-tabs button,.inbox-pages button{padding:9px 14px;border:1px solid var(--line);border-radius:4px;background:#f3f3ef;color:var(--ink);font-size:12px}.inbox-tabs button[aria-pressed=\"true\"]{background:var(--ink);color:#fff}.inbox-pages{display:flex;justify-content:space-between;gap:8px}.inbox-pages button:disabled{cursor:not-allowed}.conversation small{display:block;margin-top:5px;color:var(--muted);font-size:10px}.inbox-tabs+label{margin-bottom:12px}#archive-note{overflow-wrap:anywhere}\n","type":"text/css"},"/app.js":{"body":"const $=s=>document.querySelector(s);const escapeHTML=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nasync function api(path,options={}){const r=await fetch('/api'+path,{...options,headers:{'Content-Type':'application/json',...options.headers}});const d=await r.json();if(!r.ok)throw Object.assign(Error(d.error||'Please try again.'),{status:r.status,archived:d.archived===true});return d}const post=(p,d)=>api(p,{method:'POST',body:JSON.stringify(d)});\nfunction bubble(m){return '<div class=\"bubble '+(m.sender==='visitor'?'visitor':'team')+'\">'+escapeHTML(m.body)+'<small>'+new Date(m.created).toLocaleString([],{year:'numeric',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'})+'</small></div>'}\nconst stores=[['google','▷','Google Play'],['apple','●','App Store'],['huawei','◈','AppGallery']];\nasync function clients(){try{const items=await api('/clients');$('#client-list').innerHTML=items.length?items.map(c=>'<article class=\"client-card\"><img src=\"'+escapeHTML(c.image)+'\" alt=\"'+escapeHTML(c.name)+'\" loading=\"lazy\"><div class=\"client-body\"><h3>'+escapeHTML(c.name)+'</h3><p>'+escapeHTML(c.description)+'</p><div class=\"stores\">'+stores.filter(([k])=>c[k]).map(([k,i,l])=>'<a target=\"_blank\" rel=\"noopener noreferrer\" href=\"'+escapeHTML(c[k])+'\"><span class=\"store-icon\" aria-hidden=\"true\">'+i+'</span>'+l+' ↗</a>').join('')+'</div></div></article>').join(''):'<div class=\"empty-clients\"><div><h3>Client apps will be listed here.</h3><p>We’ll add client details and download links as their apps are released.<br>For enquiries about your own app, send us a message.</p><button class=\"text-link\" data-chat>Ask us about an app ↗</button></div><span class=\"large-star\" aria-hidden=\"true\">✦</span></div>'}catch{$('#client-list').innerHTML='<p>We couldn’t load the showcase. Please refresh to try again.</p>'}}\nif($('#client-list')){clients();$('#year').textContent=new Date().getFullYear();let chat;try{chat=JSON.parse(localStorage.getItem('brm-chat'))}catch{}const open=()=>{$('#chat-panel').hidden=false;if(chat)poll();else $('#chat-start input').focus()};document.addEventListener('click',e=>{if(e.target.closest('[data-chat],#chat-launch'))open()});$('#chat-close').onclick=()=>$('#chat-panel').hidden=true;\nfunction resetArchivedChat(){chat=null;localStorage.removeItem('brm-chat');$('#chat-messages').innerHTML='<div class=\"bubble team\">Your previous conversation has been archived after 24 hours of inactivity. Start a new chat below. The team keeps the history for future reference.</div>';delete $('#chat-messages').dataset.content;$('#chat-start').hidden=false;$('#chat-send').hidden=true;$('#voice-start').disabled=true;$('#voice-status').textContent='Start a new chat to make a voice call.';$('#chat-status').textContent=''}\nasync function poll(){if(!chat||$('#chat-panel').hidden)return;const current=chat;try{const d=await api('/chat/'+current.id,{headers:{'X-Chat-Token':current.token}});if(chat!==current)return;const el=$('#chat-messages'),atEnd=el.scrollHeight-el.scrollTop-el.clientHeight<50;const html=d.map(bubble).join('');if(el.dataset.content!==html){el.innerHTML='<div class=\"bubble team\">Tell us what you need, or ask a question. Our team will reply here. This chat clears after 24 hours without a message. The team keeps an archived copy.</div>'+html;el.dataset.content=html;if(atEnd)el.scrollTop=el.scrollHeight}$('#chat-start').hidden=true;$('#chat-send').hidden=false;$('#chat-status').textContent=''}catch(e){if(chat!==current)return;if(e.archived)resetArchivedChat();else $('#chat-status').textContent=e.message}}\n$('#chat-start').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{chat=await post('/chat',{name:e.target.name.value});localStorage.setItem('brm-chat',JSON.stringify(chat));await poll();$('#chat-send input').focus()}catch(e){$('#chat-status').textContent=e.message}finally{b.disabled=false}};$('#chat-send').onsubmit=async e=>{e.preventDefault();const input=e.target.body,b=e.target.querySelector('button');b.disabled=true;try{await post('/chat/'+chat.id,{body:input.value,token:chat.token});input.value='';await poll();$('#chat-messages').scrollTop=1e9}catch(e){if(e.archived)resetArchivedChat();else $('#chat-status').textContent=e.message}finally{b.disabled=false}};setInterval(poll,4000)}\n","type":"text/javascript"},"/admin.js":{"body":"let selected=null,clientData=[],archiveView=false,inboxOffset=0,inboxGeneration=0,archiveSearchTimer=null;\nfunction clearConversation(){selected=null;$('#chat-title').textContent='Select a conversation';$('#admin-messages').innerHTML='';delete $('#admin-messages').dataset.content;$('#reply-form').hidden=true;$('#archive-note').hidden=true}\nasync function loadInbox(){\n if($('#dashboard').hidden)return;\n const version=++inboxGeneration,view=archiveView,id=selected,offset=inboxOffset,search=view?$('#archive-search').value.trim():'';\n try{\n  const list=await api('/admin/chats?archived='+(view?'1':'0')+'&offset='+offset+'&search='+encodeURIComponent(search));if(version!==inboxGeneration)return;\n  $('#conversations').innerHTML=list.length?list.map(c=>'<button class=\"conversation '+(id===c.id?'selected':'')+'\" data-id=\"'+escapeHTML(c.id)+'\"><strong>'+escapeHTML(c.name)+'</strong> · '+c.count+' messages<small> · '+new Date(c.last_activity).toLocaleString()+(c.archived_at?' · Archived':c.last_sender==='visitor'?' · Visitor message':' · Team replied')+'</small></button>').join(''):'<p class=\"hint\">'+(view?'No archived conversations found.':'No active conversations. New visitor chats will appear here.')+'</p>';\n  $('#chats-previous').disabled=offset===0;$('#chats-next').disabled=list.length<50;\n  if(id){\n   const conversation=list.find(c=>c.id===id);if(!conversation){clearConversation();return}\n   $('#chat-title').textContent=conversation.name;$('#reply-form').hidden=view;$('#archive-note').hidden=!view;\n   if(view)$('#archive-note').textContent='Archived '+new Date(conversation.archived_at).toLocaleString()+'. Saved history is read-only. Conversation: '+conversation.id;\n   const messages=await api('/admin/chats/'+id);if(version!==inboxGeneration)return;\n   const el=$('#admin-messages'),html=messages.map(bubble).join('');if(el.dataset.content!==html){const bottom=el.scrollHeight-el.scrollTop-el.clientHeight<50;el.innerHTML=html;el.dataset.content=html;if(bottom)el.scrollTop=el.scrollHeight}\n  }\n  $('#inbox-status').textContent='';\n }catch(e){if(version===inboxGeneration)$('#inbox-status').textContent=e.message}\n}\nfunction showConversationView(archived){archiveView=archived;inboxOffset=0;clearConversation();$('#inbox-tab').setAttribute('aria-pressed',String(!archived));$('#archive-tab').setAttribute('aria-pressed',String(archived));$('#archive-search-label').hidden=!archived;loadInbox()}\n$('#inbox-tab').onclick=()=>showConversationView(false);$('#archive-tab').onclick=()=>showConversationView(true);\n$('#archive-search').oninput=()=>{clearTimeout(archiveSearchTimer);inboxGeneration++;archiveSearchTimer=setTimeout(()=>{inboxOffset=0;clearConversation();loadInbox()},250)};\n$('#chats-previous').onclick=()=>{inboxOffset=Math.max(0,inboxOffset-50);clearConversation();loadInbox()};$('#chats-next').onclick=()=>{inboxOffset+=50;clearConversation();loadInbox()};\nasync function loadClients(){clientData=await api('/clients');$('#admin-clients').innerHTML=clientData.length?clientData.map(c=>'<div class=\"admin-client\"><span>'+escapeHTML(c.name)+'</span><div><button class=\"text-link\" data-edit=\"'+c.id+'\">Edit</button> <button class=\"danger\" data-delete=\"'+c.id+'\">Delete</button></div></div>').join(''):'<p class=\"hint\">No clients added yet.</p>'}\nasync function dashboard(){$('#login').hidden=true;$('#dashboard').hidden=false;await Promise.all([loadInbox(),loadClients()])}$('#login-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await post('/login',{email:e.target.email.value,password:e.target.password.value});e.target.reset();await dashboard()}catch(e){$('#login-error').textContent=e.message}finally{b.disabled=false}};$('#logout').onclick=async()=>{await post('/logout',{});location.reload()};$('#conversations').onclick=e=>{const b=e.target.closest('[data-id]');if(!b)return;selected=b.dataset.id;$('#chat-title').textContent=b.querySelector('strong').textContent;$('#reply-form').hidden=archiveView;loadInbox()};$('#reply-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await post('/admin/chats/'+selected,{body:e.target.body.value});e.target.reset();await loadInbox();$('#admin-messages').scrollTop=1e9}catch(e){$('#inbox-status').textContent=e.message}finally{b.disabled=false}};\nfunction resetClient(){$('#client-form').reset();$('#client-form').elements.id.value='';$('#client-title').textContent='Add a client';$('#cancel-edit').hidden=true}$('#cancel-edit').onclick=resetClient;$('#admin-clients').onclick=async e=>{const edit=e.target.closest('[data-edit]'),del=e.target.closest('[data-delete]');if(edit){const c=clientData.find(x=>x.id===edit.dataset.edit),f=$('#client-form');for(const k of ['id','name','description','google','apple','huawei'])f.elements[k].value=c[k]||'';$('#client-title').textContent='Edit '+c.name;$('#cancel-edit').hidden=false;f.scrollIntoView({behavior:'smooth'})}if(del&&confirm('Delete this client from the website?')){try{await api('/admin/clients/'+del.dataset.delete,{method:'DELETE'});await loadClients()}catch(e){$('#client-status').textContent=e.message}}};\n$('#client-form').onsubmit=async e=>{e.preventDefault();const f=e.target,b=f.querySelector('button');b.disabled=true;$('#client-status').textContent='Saving…';try{const data=Object.fromEntries(['id','name','description','google','apple','huawei'].map(k=>[k,f.elements[k].value]));const file=f.image.files[0];if(file){if(file.size>2*1024*1024)throw Error('Please choose an image smaller than 2 MB.');data.image=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}await post('/admin/clients',data);resetClient();await loadClients();$('#client-status').textContent='Published. Your client is now visible on the website.'}catch(e){$('#client-status').textContent=e.message}finally{b.disabled=false}};api('/admin/session').then(dashboard).catch(()=>{});setInterval(loadInbox,5000);\n","type":"text/javascript"},"/voice.js":{"body":"(()=>{\nconst isAdmin=!!document.querySelector('#admin-voice');if(!document.querySelector('#visitor-voice')&&!isAdmin)return;\nconst el=id=>document.getElementById(id),status=message=>el('voice-status').textContent=message;\nlet call=null,pc=null,stream=null,cursor=0,candidates=[],pending=[],busy=false,pollBusy=false,available=false,incoming=null,ringTimer=null,ringContext=null,ringing=false,started=0,disconnectTimer=null,generation=0,playbackBlocked=false;\nconst supported=!!(window.RTCPeerConnection&&navigator.mediaDevices?.getUserMedia);\nconst audio=document.createElement('audio');audio.autoplay=true;audio.setAttribute('playsinline','');document.body.append(audio);\nfunction identity(){try{return JSON.parse(localStorage.getItem('brm-chat'))}catch{return null}}\nasync function request(path,data){const c=identity();return api((isAdmin?'/admin/voice/':'/voice/')+path,{method:data?'POST':'GET',headers:isAdmin?{}:{'X-Chat-Id':c?.id||'','X-Chat-Token':c?.token||''},...(data?{body:JSON.stringify(data)}:{})})}\nfunction controls(show){el('voice-controls').hidden=!show;if(el('voice-start'))el('voice-start').hidden=show;el('voice-mute').textContent='Mute';el('voice-mute').setAttribute('aria-pressed','false')}\nfunction stopRing(){clearInterval(ringTimer);ringTimer=null;ringing=false}\nfunction ring(){if(ringing)return;ringing=true;const tone=()=>{if(!ringContext||ringContext.state!=='running')return;const oscillator=ringContext.createOscillator(),gain=ringContext.createGain();oscillator.connect(gain);gain.connect(ringContext.destination);oscillator.frequency.value=660;gain.gain.setValueAtTime(.08,ringContext.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ringContext.currentTime+.3);oscillator.start();oscillator.stop(ringContext.currentTime+.3)};tone();ringTimer=setInterval(tone,1800)}\n// The spoken introduction plays once; only the owner-supplied 6:00–6:30 music excerpt loops.\nconst holdIntroSeconds=1.995532879818594;\nlet holdContext=null,holdSource=null,holdGain=null,holdBuffer=null,holdLoading=null,holdWanted=false;\nfunction prepareHoldMusic(){\n if(isAdmin)return;\n try{\n  const Context=window.AudioContext||window.webkitAudioContext;if(!Context)return;\n  holdContext ||= new Context();holdContext.resume().catch(()=>{});\n  if(!holdBuffer&&!holdLoading){\n   holdLoading=fetch('/waiting-music.m4a').then(response=>{if(!response.ok)throw Error('Waiting music unavailable');return response.arrayBuffer()})\n   .then(bytes=>holdContext.decodeAudioData(bytes)).then(buffer=>{holdBuffer=buffer;holdLoading=null;if(holdWanted)startHoldMusic()})\n   .catch(()=>{holdLoading=null;});\n  }\n }catch{}\n}\nfunction stopHoldMusic(){\n holdWanted=false;\n if(holdSource){try{holdSource.stop()}catch{}holdSource.disconnect();holdSource=null}\n if(holdGain){holdGain.disconnect();holdGain=null}\n}\nfunction resumeHoldMusic(){\n if(!holdContext||!holdWanted)return;\n return holdContext.resume().then(()=>{if(holdWanted&&holdContext.state==='running')resume.hidden=true}).catch(()=>{if(holdWanted)resume.hidden=false});\n}\nfunction startHoldMusic(){\n holdWanted=true;if(!holdContext||!holdBuffer||holdSource)return;\n try{\n  holdGain=holdContext.createGain();holdGain.gain.value=.3;holdGain.connect(holdContext.destination);\n  holdSource=holdContext.createBufferSource();holdSource.buffer=holdBuffer;holdSource.loop=true;holdSource.loopStart=holdIntroSeconds;holdSource.loopEnd=holdBuffer.duration;holdSource.connect(holdGain);holdSource.start();\n  if(holdContext.state!=='running'){resume.hidden=false;resumeHoldMusic()}\n }catch{stopHoldMusic()}\n}\nfunction cleanup(message){generation++;playbackBlocked=false;resume.hidden=true;stopRing();stopHoldMusic();clearTimeout(disconnectTimer);if(pc){pc.onconnectionstatechange=null;pc.onicecandidate=null;pc.close()}pc=null;stream?.getTracks().forEach(t=>t.stop());stream=null;audio.srcObject=null;call=null;cursor=0;pending=[];candidates=[];started=0;controls(false);if(el('incoming-call'))el('incoming-call').hidden=true;status(message)}\nasync function end(message='Call ended.',decline=false){const id=call?.id||incoming?.id;cleanup(message);incoming=null;if(id)try{await request(id+'/end',{decline})}catch{status(message+' The connection will close automatically.')}}\nfunction checkCall(version){if(version!==generation)throw Object.assign(Error('Call cancelled.'),{name:'AbortError'});}\nfunction prepareAudio(){audio.muted=false;audio.volume=1;audio.srcObject=new MediaStream();audio.play().catch(()=>{});}\nfunction playRemoteAudio(){const version=generation;return audio.play().catch(()=>{if(version!==generation)return;playbackBlocked=true;resume.hidden=false;status('Tap Resume audio to hear the call.');});}\nasync function setup(){const version=generation;const media=await navigator.mediaDevices.getUserMedia({audio:true,video:false});if(version!==generation){media.getTracks().forEach(t=>t.stop());throw Error('Call cancelled.')}stream=media;const config=await request('ice');if(version!==generation)throw Error('Call cancelled.');const connection=new RTCPeerConnection({iceServers:config.iceServers});pc=connection;stream.getTracks().forEach(t=>pc.addTrack(t,stream));pc.ontrack=e=>{if(version!==generation)return;const remote=audio.srcObject||new MediaStream();audio.srcObject=remote;if(!remote.getTracks().some(t=>t.id===e.track.id))remote.addTrack(e.track);e.track.onunmute=()=>{if(audio.srcObject===remote)playRemoteAudio()};playRemoteAudio();};pc.onicecandidate=e=>{if(!e.candidate)return;const candidate=JSON.stringify(e.candidate.toJSON());if(call)request(call.id+'/candidate',{candidate}).catch(()=>{});else candidates.push(candidate)};pc.onconnectionstatechange=()=>{if(version!==generation||pc!==connection)return;if(pc.connectionState==='connected'){stopHoldMusic();clearTimeout(disconnectTimer);status(playbackBlocked?'Tap Resume audio to hear the call.':'On a voice call');if(!started)started=Date.now()}if(pc.connectionState==='failed')end('The call could not connect on this network. Please use chat.');if(pc.connectionState==='disconnected'){status('Connection lost. Trying to reconnect…');clearTimeout(disconnectTimer);disconnectTimer=setTimeout(()=>end('Call disconnected. Please try again or use chat.'),12000)}};\nreturn connection;\n}\nasync function flush(version){const id=call?.id;const batch=candidates.splice(0);for(const candidate of batch){checkCall(version);await request(id+'/candidate',{candidate});checkCall(version)}}\nfunction failure(e){return e.name==='NotAllowedError'?'Microphone access was blocked. Open the site controls beside the browser address, set Microphone to Allow, then try again.':e.name==='NotFoundError'?'No microphone found. Connect one and try again.':e.message||'Could not start the call. Please try again.'}\nif(!supported){status('Voice calls are not supported in this browser. Please use chat.');if(el('voice-available'))el('voice-available').disabled=true;return}\nconst resume=document.createElement('button');resume.type='button';resume.textContent='Resume audio';resume.hidden=true;audio.onpause=()=>{if(call&&audio.srcObject)resume.hidden=false};audio.onplaying=()=>{playbackBlocked=false;resume.hidden=true;if(pc?.connectionState==='connected')status('On a voice call')};resume.onclick=()=>{if(holdWanted)return resumeHoldMusic();audio.muted=false;audio.volume=1;return playRemoteAudio()};el(isAdmin?'admin-voice':'visitor-voice').append(resume);\nel('voice-mute').onclick=()=>{if(!stream)return;const muted=stream.getAudioTracks().some(t=>t.enabled);stream.getAudioTracks().forEach(t=>t.enabled=!muted);el('voice-mute').textContent=muted?'Unmute':'Mute';el('voice-mute').setAttribute('aria-pressed',String(muted))};el('voice-end').onclick=()=>end();\nif(isAdmin){\n el('voice-available').onchange=async e=>{const checkbox=e.target,wanted=checkbox.checked;checkbox.disabled=true;try{if(wanted){status('Please allow microphone access when your browser asks.');const permissionStream=await navigator.mediaDevices.getUserMedia({audio:true,video:false});permissionStream.getTracks().forEach(track=>track.stop());ringContext ||= new (window.AudioContext||window.webkitAudioContext)();await ringContext.resume()}await request('presence',{available:wanted});available=wanted;status(available?'Microphone allowed. Ready for calls. Keep this dashboard open.':'You are not taking calls.')}catch(error){available=false;checkbox.checked=false;request('presence',{available:false}).catch(()=>{});status(failure(error))}finally{checkbox.disabled=false}};\n el('voice-answer').onclick=async()=>{\n  if(busy||!incoming)return;busy=true;el('voice-answer').disabled=true;\n  const version=generation,incomingId=incoming.id;call={id:incomingId};controls(true);stopRing();el('incoming-call').hidden=true;status('Connecting…');prepareAudio();\n  try{\n   const connection=await setup();checkCall(version);\n   const info=await request(incomingId);checkCall(version);if(info.state!=='ringing')throw Error('This call has ended.');\n   await connection.setRemoteDescription({type:'offer',sdp:info.offer});checkCall(version);\n   const answer=await connection.createAnswer();checkCall(version);await connection.setLocalDescription(answer);checkCall(version);\n   await request(incomingId+'/answer',{answer:connection.localDescription.sdp});checkCall(version);await flush(version);\n  }catch(error){if(version===generation)await end(failure(error))}finally{busy=false;el('voice-answer').disabled=false}\n };\n el('voice-decline').onclick=()=>end('Call declined.',true);\n el('logout').addEventListener('click',()=>{available=false;request('presence',{available:false}).catch(()=>{});if(call||incoming)end()});\n}else{\n el('voice-start').onclick=async()=>{\n  if(busy||call)return;busy=true;const version=generation;el('voice-start').disabled=true;status('Allow microphone access to call the team.');controls(true);prepareAudio();prepareHoldMusic();\n  try{\n   const connection=await setup();checkCall(version);const offer=await connection.createOffer();checkCall(version);\n   await connection.setLocalDescription(offer);checkCall(version);\n   const created=await request('start',{offer:connection.localDescription.sdp});\n   if(version!==generation){await request(created.id+'/end',{});return}\n   call=created;status('Calling Black R Media…');startHoldMusic();await flush(version);\n  }catch(error){if(version===generation)await end(failure(error))}finally{busy=false}\n };\n}\nasync function tick(){if(pollBusy||busy)return;pollBusy=true;try{\n if(isAdmin){if(el('dashboard').hidden){if(call||stream)cleanup('Signed out.');available=false;return}if(available)await request('presence',{available:true});if(!call){const next=await request('incoming');if(next?.state==='ringing'&&available){incoming=next;el('caller-name').textContent='Incoming call from '+next.name;el('incoming-call').hidden=false;status('Incoming voice call');ring()}else{incoming=null;el('incoming-call').hidden=true;stopRing()} }}\n else if(!call){const c=identity();if(!c){el('voice-start').disabled=true;el('voice-start').dataset.state='unavailable';el('voice-start').textContent='Call the team';return}const presence=await request('presence');const button=el('voice-start');button.disabled=!presence.available||presence.busy;button.dataset.state=presence.busy?'busy':presence.available?'available':'unavailable';button.textContent=presence.busy?'Currently on a call':'Call the team';status(presence.busy?'The team is currently on a call. Please leave a message or try again shortly.':!presence.available?'The team is not taking calls right now. You can leave a message.':'The team is available for a voice call.');}\n if(call){const version=generation,id=call.id;const info=await request(id+'?after='+cursor);if(version!==generation||call?.id!==id)return;if(['ended','declined'].includes(info.state)){cleanup(info.state==='declined'?'The team couldn’t take your call. Please leave a message.':'Call ended.');return}if(!pc)return;if(!isAdmin&&info.answer){stopHoldMusic();if(!pc.remoteDescription)await pc.setRemoteDescription({type:'answer',sdp:info.answer});if(version!==generation)return;}for(const s of info.signals){pending.push(JSON.parse(s.candidate));cursor=Math.max(cursor,s.seq)}if(pc.remoteDescription){while(pending.length){await pc.addIceCandidate(pending.shift());if(version!==generation)return}}if(info.state==='connected'&&pc.connectionState!=='connected')status('Connecting audio…');}\n }catch(error){if(call)status('Checking the call connection…');else if(isAdmin&&available){status('Connection interrupted. Check your internet connection.')} }finally{pollBusy=false}}\nsetInterval(tick,2500);tick();window.addEventListener('pagehide',()=>{const id=call?.id||incoming?.id;const c=identity();const headers={'Content-Type':'application/json'};if(!isAdmin){headers['X-Chat-Id']=c?.id||'';headers['X-Chat-Token']=c?.token||''}const root='/api/'+(isAdmin?'admin/':'')+'voice/';if(id)fetch(root+id+'/end',{method:'POST',headers,body:'{}',keepalive:true}).catch(()=>{});if(isAdmin&&available)fetch(root+'presence',{method:'POST',headers,body:'{\"available\":false}',keepalive:true}).catch(()=>{});cleanup('Call ended.');});\n})();\n","type":"text/javascript"},"/logo.png":{"body":"","type":"image/png","base64":true},"/waiting-music.m4a":{"body":"","type":"audio/mp4","base64":true}};
